 	// TODO(roberts): finish the implementation of this.
 }
+
+const (
+	maxEncodedShapes        = 100000000
+	maxEncodedIndexCells    = 100000000
+	maxClippedShapesPerCell = 1000000
+	maxEdgesPerClippedShape = 10000000
+)
+
+// Encode encodes the ShapeIndex to the given io.Writer.
+func (s *ShapeIndex) Encode(w io.Writer) error {
+	s.maybeApplyUpdates()
+
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	e := &encoder{w: w}
+	e.writeInt8(encodingVersion)
+	e.writeInt32(int32(s.maxEdgesPerCell))
+	e.writeInt32(s.nextID)
+
+	// Encode shapes map.
+	e.writeUint32(uint32(len(s.shapes)))
+	shapeIDs := make([]int32, 0, len(s.shapes))
+	for id := range s.shapes {
+		shapeIDs = append(shapeIDs, id)
+	}
+	slices.Sort(shapeIDs)
+
+	for _, id := range shapeIDs {
+		shape := s.shapes[id]
+		tag := shape.typeTag()
+		if tag == typeTagNone {
+			return fmt.Errorf("shape ID %d of type %T cannot be encoded (typeTag is typeTagNone)", id, shape)
+		}
+		e.writeInt32(id)
+		e.writeUvarint(uint64(tag))
+
+		type encoderShape interface {
+			Encode(w io.Writer) error
+		}
+		if enc, ok := shape.(encoderShape); ok {
+			if err := enc.Encode(e.w); err != nil {
+				return fmt.Errorf("failed to encode shape ID %d: %w", id, err)
+			}
+		} else {
+			return fmt.Errorf("shape ID %d of type %T does not implement Encode", id, shape)
+		}
+	}
+
+	// Encode cells and spatial structure.
+	e.writeUint32(uint32(len(s.cells)))
+	for _, cellID := range s.cells {
+		cell := s.cellMap[cellID]
+		if cell == nil {
+			return fmt.Errorf("missing cell for cellID %v", cellID)
+		}
+		e.writeUint64(uint64(cellID))
+		e.writeUint32(uint32(len(cell.shapes)))
+		for _, cs := range cell.shapes {
+			e.writeInt32(cs.shapeID)
+			e.writeBool(cs.containsCenter)
+			e.writeUint32(uint32(len(cs.edges)))
+			for _, edgeID := range cs.edges {
+				e.writeInt32(int32(edgeID))
+			}
+		}
+	}
+
+	return e.err
+}
+
+// Decode decodes a ShapeIndex from the given io.Reader.
+func (s *ShapeIndex) Decode(r io.Reader) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	s.shapes = make(map[int32]Shape)
+	s.nextID = 0
+	s.cellMap = make(map[CellID]*ShapeIndexCell)
+	s.cells = nil
+	s.pendingAdditionsPos = 0
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+
+	br := asByteReader(r)
+	d := &decoder{r: br}
+
+	version := d.readInt8()
+	if d.err != nil {
+		return d.err
+	}
+	if version != encodingVersion {
+		return fmt.Errorf("unsupported ShapeIndex encoding version %d", version)
+	}
+
+	maxEdges := d.readInt32()
+	if d.err != nil {
+		return d.err
+	}
+	if maxEdges <= 0 {
+		return fmt.Errorf("invalid maxEdgesPerCell: %d", maxEdges)
+	}
+
+	nextID := d.readInt32()
+	if d.err != nil {
+		return d.err
+	}
+	if nextID < 0 {
+		return fmt.Errorf("invalid nextID: %d", nextID)
+	}
+
+	numShapes := d.readUint32()
+	if d.err != nil {
+		return d.err
+	}
+	if numShapes > maxEncodedShapes {
+		return fmt.Errorf("too many shapes (%d; max is %d)", numShapes, maxEncodedShapes)
+	}
+
+	s.shapes = make(map[int32]Shape, numShapes)
+	var maxID int32 = -1
+
+	for i := uint32(0); i < numShapes; i++ {
+		shapeID := d.readInt32()
+		if d.err != nil {
+			return d.err
+		}
+		if shapeID < 0 {
+			return fmt.Errorf("invalid shapeID: %d", shapeID)
+		}
+		if _, exists := s.shapes[shapeID]; exists {
+			return fmt.Errorf("duplicate shapeID: %d", shapeID)
+		}
+
+		shape, err := decodeShape(d)
+		if err != nil {
+			return fmt.Errorf("failed to decode shape ID %d: %w", shapeID, err)
+		}
+
+		s.shapes[shapeID] = shape
+		if shapeID > maxID {
+			maxID = shapeID
+		}
+	}
+
+	if nextID <= maxID {
+		nextID = maxID + 1
+	}
+
+	numCells := d.readUint32()
+	if d.err != nil {
+		return d.err
+	}
+	if numCells > maxEncodedIndexCells {
+		return fmt.Errorf("too many cells (%d; max is %d)", numCells, maxEncodedIndexCells)
+	}
+
+	s.cells = make([]CellID, numCells)
+	s.cellMap = make(map[CellID]*ShapeIndexCell, numCells)
+
+	var prevCellID CellID
+	for i := uint32(0); i < numCells; i++ {
+		cellIDVal := d.readUint64()
+		if d.err != nil {
+			return d.err
+		}
+		cellID := CellID(cellIDVal)
+		if i > 0 && cellID <= prevCellID {
+			return fmt.Errorf("cells out of order or duplicate: cellID %v <= prevCellID %v", cellID, prevCellID)
+		}
+		prevCellID = cellID
+
+		numClipped := d.readUint32()
+		if d.err != nil {
+			return d.err
+		}
+		if numClipped > maxClippedShapesPerCell {
+			return fmt.Errorf("too many clipped shapes in cell (%d; max is %d)", numClipped, maxClippedShapesPerCell)
+		}
+
+		cell := NewShapeIndexCell(int(numClipped))
+		for j := uint32(0); j < numClipped; j++ {
+			shapeID := d.readInt32()
+			containsCenter := d.readBool()
+			numEdges := d.readUint32()
+			if d.err != nil {
+				return d.err
+			}
+			if numEdges > maxEdgesPerClippedShape {
+				return fmt.Errorf("too many edges in clipped shape (%d; max is %d)", numEdges, maxEdgesPerClippedShape)
+			}
+
+			shape := s.shapes[shapeID]
+			if shape == nil {
+				return fmt.Errorf("clipped shape references non-existent shapeID %d", shapeID)
+			}
+
+			cs := newClippedShape(shapeID, int(numEdges))
+			cs.containsCenter = containsCenter
+			for k := uint32(0); k < numEdges; k++ {
+				edgeID := d.readInt32()
+				if edgeID < 0 || edgeID >= int32(shape.NumEdges()) {
+					return fmt.Errorf("invalid edgeID %d in clipped shape %d (shape has %d edges)", edgeID, shapeID, shape.NumEdges())
+				}
+				cs.edges[k] = int(edgeID)
+			}
+			if d.err != nil {
+				return d.err
+			}
+			cell.shapes[j] = cs
+		}
+
+		s.cells[i] = cellID
+		s.cellMap[cellID] = cell
+	}
+
+	s.maxEdgesPerCell = int(maxEdges)
+	s.nextID = nextID
+	s.pendingAdditionsPos = s.nextID
+	s.pendingRemovals = nil
+	atomic.StoreInt32(&s.status, fresh)
+
+	return nil
+}
+
+func decodeShape(d *decoder) (Shape, error) {
+	tagVal := d.readUvarint()
+	if d.err != nil {
+		return nil, d.err
+	}
+	tag := typeTag(tagVal)
+
+	switch tag {
+	case typeTagPolygon:
+		p := &Polygon{}
+		if err := p.Decode(d.r); err != nil {
+			return nil, err
+		}
